import { requirePagePermission } from "@/lib/portal-admin";
import RoomManagementShell from "../components/room-management-shell";
import { redirect } from "next/navigation";
import { auth } from "../../../auth";
import { prisma } from "@/lib/prisma";
export default async function ContentModerationPage(){await requirePagePermission("content.view");
  const session=await auth();if(!session?.user)redirect("/");const [posts,blocks,requests]=await Promise.all([prisma.post.findMany({include:{author:{select:{publicId:true,name:true}}},orderBy:{createdAt:"desc"},take:100}),prisma.userBlock.findMany({include:{blocker:{select:{publicId:true,name:true}},blocked:{select:{publicId:true,name:true}}},orderBy:{createdAt:"desc"},take:100}),prisma.friendRequest.findMany({include:{requester:{select:{publicId:true,name:true}},addressee:{select:{publicId:true,name:true}}},orderBy:{createdAt:"desc"},take:100})]);return <RoomManagementShell title="Content & Social Safety"><div className="space-y-7"><div><h2 className="text-2xl font-bold">Social activity review</h2><p className="mt-1 text-sm text-[#71847f]">Read-only visibility is enabled. Destructive moderation remains disabled until the administrator permission policy is approved.</p></div><div className="grid gap-3 sm:grid-cols-3">{[["Recent posts",posts.length],["User blocks",blocks.length],["Friend requests",requests.length]].map(([k,v])=><div key={k} className="rounded-2xl border border-[#dfe9e7] bg-white p-5"><p className="text-xs font-semibold text-[#71847f]">{k}</p><p className="mt-2 text-2xl font-bold">{v}</p></div>)}</div><section className="rounded-2xl border border-[#dfe9e7] bg-white p-5"><h3 className="font-bold">Recent posts</h3><div className="mt-3 divide-y">{posts.map(p=><div key={p.publicId} className="py-3 text-sm"><b>{p.author.name}</b> <span className="text-xs text-[#71847f]">{p.author.publicId} · {p.publicId}</span><p className="mt-1 text-[#526b67]">{p.description||"Image post"}</p></div>)}{!posts.length&&<p className="py-6 text-sm text-[#71847f]">No posts.</p>}</div></section><div className="grid gap-5 lg:grid-cols-2"><section className="rounded-2xl border border-[#dfe9e7] bg-white p-5"><h3 className="font-bold">User block relationships</h3><div className="mt-3 divide-y">{blocks.map((b,i)=><p key={`${b.blocker.publicId}-${b.blocked.publicId}-${i}`} className="py-3 text-sm"><b>{b.blocker.name}</b> blocked <b>{b.blocked.name}</b><br/><span className="text-xs text-[#71847f]">{new Date(b.createdAt).toLocaleString()}</span></p>)}{!blocks.length&&<p className="py-6 text-sm text-[#71847f]">No user blocks.</p>}</div></section><section className="rounded-2xl border border-[#dfe9e7] bg-white p-5"><h3 className="font-bold">Friend requests</h3><div className="mt-3 divide-y">{requests.map(r=><p key={r.publicId} className="py-3 text-sm"><b>{r.requester.name}</b> → <b>{r.addressee.name}</b><br/><span className="text-xs text-[#71847f]">{r.status} · {new Date(r.createdAt).toLocaleString()}</span></p>)}{!requests.length&&<p className="py-6 text-sm text-[#71847f]">No friend requests.</p>}</div></section></div></div></RoomManagementShell>}
